@php($payload=$trackingPayload)
@php($money=fn($n)=>app(\App\Support\StorefrontCurrencyContext::class)->formatSnapshot($n,$payload['currency'],$payload['currencyExchangeRate']??1))
<h1>Your order, in progress.</h1><p class="te-tracking-reference">Order {{ $payload['number'] }} <span class="te-status">{{ $payload['statusLabel'] }}</span></p>
<div class="te-tracking-result-grid"><div><section class="te-tracking-updates"><h2>Latest update</h2>@foreach($payload['timeline'] as $event)<article><h3>{{ $event['title'] }}</h3>@if($event['timestamp'])<time>{{ \Carbon\Carbon::parse($event['timestamp'])->format('d M Y') }}</time>@endif<p>{{ $event['description'] }}</p>@if($event['location'])<small>{{ $event['location'] }}</small>@endif</article>@endforeach</section>
<section class="te-tracking-identifiers"><h2>Tracking reference</h2><div><section><small>Tracking number</small><p>{{ $payload['tracking']['number']?:'Not available yet' }}</p>@if($payload['tracking']['number'])<button class="te-link" x-data="{copied:false}" @click="navigator.clipboard.writeText(@js($payload['tracking']['number']));copied=true" x-text="copied?'Copied':'Copy tracking number'">Copy tracking number</button>@endif</section><section><small>Courier</small><p>{{ $payload['tracking']['carrier']?:'Not available yet' }}</p></section></div></section>
<section><h2>Shipping to</h2>@if($payload['address']??null)<address>{{ $payload['address']['line1'] }}<br>{{ $payload['address']['city'] }} {{ $payload['address']['postalCode'] }}</address>@endif</section></div><section class="te-selected"><h2>Your order</h2>@foreach($payload['items'] as $item)<article class="te-selected-item">@if($item['imageUrl'])<img src="{{ $item['imageUrl'] }}" alt="{{ $item['title'] }}">@endif<div><h3>{{ $item['title'] }}</h3><p>{{ $item['variantTitle'] }}</p><p>Qty {{ $item['quantity'] }}</p></div><strong>{{ $money($item['lineTotal']) }}</strong></article>@endforeach<dl>@foreach(['subtotal'=>'Subtotal','discount'=>'Discount','shipping'=>'Shipping','tax'=>'Tax','total'=>'Total'] as $key=>$label)@if(in_array($key,['subtotal','shipping','total'])||($payload['totals'][$key]??0))<div><dt>{{ $label }}</dt><dd>{{ $money($payload['totals'][$key]??0) }}</dd></div>@endif@endforeach</dl></section></div><a class="te-tracking-continue" href="{{ route('storefront.index') }}">Continue shopping →</a>
